WITH pi AS (SELECT regexp_extract(Project_Information, 'The project ([^ ]+)', 1) AS ProjectName, regexp_extract(Project_Information, '([0-9]+) stars', 1) AS stars_s FROM project_info), pi2 AS (SELECT ProjectName, CAST(stars_s AS BIGINT) AS stars FROM pi WHERE ProjectName <> '' AND stars_s <> '') SELECT ppv.Name, ppv.Version, ppv.ProjectName, pi2.stars FROM project_packageversion ppv JOIN pi2 ON ppv.ProjectName = pi2.ProjectName WHERE ppv.System='NPM' AND ppv.RelationType='SOURCE_REPO_TYPE'
